pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256) public {
        // The require gate admits only msg.sender == depositorAccount (initially address(0)).
        // Drive a *successful* call from the depositor account with arbitrary fuzzed values.
        vm.prank(c.depositorAccount());
        c.setL1BlockValues(1, 2, 3, bytes32(uint256(4)), 5, bytes32(uint256(6)), 7, 8);
        // For any admissible successful call, C never writes timestamp, so it stays 0;
        // the mutant stores _timestamp, making c.timestamp() != 0.
        assertTrue(c.timestamp() == 0);
    }
